/**
 * VirtueMart read methods refuse with 501 NOT_SUPPORTED before any request.
 *
 * VirtueMart documents no REST or JSON list API. Its "VM API" page
 * (https://docs.virtuemart.net/vm-api) says "The VirtueMart API documentation
 * is generated by the tool Doxygen." and that reference
 * (https://api.virtuemart.net/files.html) lists the site views: there is no
 * `products`, `categories` or `users` view at all, and `orders` ships only
 * `view.html.php` (the logged-in shopper's own orders page). The adapter used
 * to call `index.php?option=com_virtuemart&view=<view>&format=json` on those
 * views, which never returns JSON.
 */
import { afterEach, describe, expect, it, vi } from 'vitest'
import axios from 'axios'
import type { Credentials, QueryParams } from '@opensteward/shared'
import { VirtueMartAdapter } from '../../../../../../src/verticals/ecommerce/adapters/virtuemart/index'

const CREDS = {
  accessToken: 'tok',
  extra: { baseUrl: 'https://shop.example.com' },
} as unknown as Credentials

const PARAMS: QueryParams = { page: 1, limit: 10 }

function stubAxios() {
  const get = vi.fn(async () => ({ data: [] }))
  const post = vi.fn(async () => ({ data: {} }))
  const create = vi.spyOn(axios, 'create').mockReturnValue({ get, post, defaults: {} } as never)
  const fetchSpy = vi.spyOn(globalThis, 'fetch').mockResolvedValue(new Response('{}'))
  return { get, post, create, fetchSpy }
}

afterEach(() => {
  vi.restoreAllMocks()
})

const adapter = new VirtueMartAdapter()

const CALLS: Array<[string, () => Promise<unknown>, RegExp]> = [
  ['listProducts', () => adapter.listProducts(CREDS, PARAMS), /cannot list products/],
  ['listOrders', () => adapter.listOrders(CREDS, PARAMS), /cannot list orders/],
  ['listCustomers', () => adapter.listCustomers(CREDS, PARAMS), /cannot list customers/],
  ['listCollections', () => adapter.listCollections(CREDS, PARAMS), /cannot list collections/],
  [
    'listInventoryLevels',
    () => adapter.listInventoryLevels(CREDS, PARAMS),
    /cannot list inventory levels/,
  ],
  ['getProduct', () => adapter.getProduct(CREDS, '1'), /cannot read a product/],
  ['getOrder', () => adapter.getOrder(CREDS, '1'), /cannot read an order/],
  ['getCustomer', () => adapter.getCustomer(CREDS, '1'), /cannot read a customer/],
  ['getCollection', () => adapter.getCollection(CREDS, '1'), /cannot read a collection/],
  [
    'getInventoryLevel',
    () => adapter.getInventoryLevel(CREDS, '1:default'),
    /cannot read an inventory level/,
  ],
]

describe('VirtueMart read methods refuse before sending anything', () => {
  for (const [name, call, message] of CALLS) {
    it(`${name} throws 501 NOT_SUPPORTED and sends no request`, async () => {
      const { get, post, create, fetchSpy } = stubAxios()
      await expect(call()).rejects.toMatchObject({
        statusCode: 501,
        code: 'NOT_SUPPORTED',
        message: expect.stringMatching(message),
      })
      expect(create).not.toHaveBeenCalled()
      expect(get).not.toHaveBeenCalled()
      expect(post).not.toHaveBeenCalled()
      expect(fetchSpy).not.toHaveBeenCalled()
    })
  }
})
